package main

import (
	"strings"
	"testing"
)

const snippet = `
static void f(void)
{
    static const uint8_t g_rows[2][4] = {
        { 1,2,3,4 },
        { 5,6 }
    };
    static const float g_flat[] =  { 0.5f,-1,2.25e-3f, 7 };
}
`

func TestTablesAreCopiedAsDeclared(t *testing.T) {
	text, err := render(snippet, []table{{"g_rows", "rows"}, {"g_flat", "flat"}})
	if err != nil {
		t.Fatal(err)
	}
	for _, want := range []string{
		"// Code generated by genminimp3 from minimp3.h of https://github.com/lieff/minimp3 at commit " + commit + ", public domain under CC0 1.0. DO NOT EDIT.\n",
		"var rows = [2][4]uint8{\n\t{1, 2, 3, 4},\n\t{5, 6},\n}\n",
		"var flat = [...]float32{\n\t0.5, -1, 2.25e-3, 7,\n}\n",
	} {
		if !strings.Contains(string(text), want) {
			t.Errorf("no %q in\n%s", want, text)
		}
	}
}

func TestWhatIsNotATableOfNumbersIsRefused(t *testing.T) {
	rows := []table{{"g_rows", "rows"}}
	for _, c := range []struct {
		name, src string
		tables    []table
	}{
		{"missing", snippet, []table{{"g_absent", "absent"}}},
		{"an expression", "static const uint8_t g_rows[2] = { 1, 1 << 2 };", rows},
		{"a pointer", "static const char *g_rows[2] = { 0, 0 };", rows},
		{"unterminated", "static const uint8_t g_rows[2] = { 1, 2 ", rows},
		{"twice", "static const uint8_t g_rows[1] = { 1 }; static const uint8_t g_rows[1] = { 2 };", rows},
	} {
		if text, err := render(c.src, c.tables); err == nil {
			t.Errorf("%s: rendered\n%s", c.name, text)
		}
	}
}

func TestOnlyThePinnedHeaderIsRead(t *testing.T) {
	if _, err := generate([]byte(snippet)); err == nil || !strings.Contains(err.Error(), commit) {
		t.Errorf("a header of another digest: %v, want an error naming the pinned commit", err)
	}
}
